template:
@php
    $html = is_string($body) ? trim($body) : '';
    if ($html !== '' && ! str_starts_with($html, '<')) {
        $html = implode('', array_map(static fn (string $line): string => '<p>'.e(trim($line)).'</p>', preg_split('/\R+/u', $html) ?: []));
    }
@endphp
@if ($heading || $html !== '')
<section class="b-text b-text--{{ $width === 'wide' ? 'wide' : 'narrow' }}" data-wx-block="text">
    <div class="b-text__inner site-prose">
        @if ($heading)
            <h2 class="b-text__heading">{{ $heading }}</h2>
        @endif
        @if ($html !== '')
            <div class="b-text__body">{!! $html !!}</div>
        @endif
    </div>
</section>
@endif

styles:
.b-text {
    padding-block: var(--site-space-5);
}

.b-text--narrow .b-text__inner {
    max-width: 42rem;
}

.b-text__heading {
    margin: 0 0 var(--site-space-4);
}

.b-text__body > :first-child {
    margin-top: 0;
}

.b-text__body > :last-child {
    margin-bottom: 0;
}
